def local_alignment(s, t):

    n = len(s)
    m = len(t)

    # Create DP table
    # v[i][j] = best score of a LOCAL alignment
    # between the first i characters of s
    # and the first j characters of t
    """ Unlike global alignment, we don't initialize the first row and column according to penalties since 
    local alignment can start anywhere. ("" vs M match is 0 in local alignment)
    The initial table is:
      ""  P  E  N  A  L  T  Y
""     0  0  0  0  0  0  0  0
M      0  0  0  0  0  0  0  0
E      0  0  0  0  0  0  0  0
A      0  0  0  0  0  0  0  0
N      0  0  0  0  0  0  0  0
L      0  0  0  0  0  0  0  0
Y      0  0  0  0  0  0  0  0
    """
    v = [[0] * (m + 1) for _ in range(n + 1)]

    # Create backtrack table
    backtrack = [[""] * (m + 1) for _ in range(n + 1)]

    # Keep track of the highest score anywhere in the table
    max_score = 0

    # Position where the highest score occurs
    max_i = 0
    max_j = 0

    # Fill DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):

            # Option 1: align s[i-1] with a gap
            from_up = v[i - 1][j] - 5

            # Option 2: align t[j-1] with a gap
            from_left = v[i][j - 1] - 5

            # Option 3: align s[i-1] with t[j-1]
            # PAM250 already tells us the score:
            # positive = favorable
            # negative = unfavorable
            from_diagonal = (
                v[i - 1][j - 1]
                + PAM_250_scoring_matrix[s[i - 1]][t[j - 1]])

            # Local alignment allows us to start a new alignment
            # at any position, so 0 is also an option unlike global alignment
            best = max(0, from_up, from_left, from_diagonal)

            v[i][j] = best # 0 seçilirse score 0'lanır, diğer ihtimallerden seçilirse score güncellenir

            # Remember where the best score came from
            if best == 0:
                backtrack[i][j] = "0"

            elif best == from_up:
                backtrack[i][j] = "↓"

            elif best == from_left:
                backtrack[i][j] = "→"

            else:
                backtrack[i][j] = "↘"

            # Check whether this is the best score
            # we have seen anywhere in the table
            if v[i][j] > max_score:
                max_score = v[i][j]
                max_i = i
                max_j = j

    # Reconstruct the local alignment
    alignment_s = ""
    alignment_t = ""

    # IMPORTANT:
    # Start at the cell with the maximum score,
    # not at the bottom-right corner
    i = max_i
    j = max_j

    # Stop when we reach a cell with score 0
    while i > 0 and j > 0 and v[i][j] != 0:

        if backtrack[i][j] == "↓":

            alignment_s = s[i - 1] + alignment_s
            alignment_t = "-" + alignment_t

            i -= 1

        elif backtrack[i][j] == "→":

            alignment_s = "-" + alignment_s
            alignment_t = t[j - 1] + alignment_t

            j -= 1

        elif backtrack[i][j] == "↘":

            alignment_s = s[i - 1] + alignment_s
            alignment_t = t[j - 1] + alignment_t

            i -= 1
            j -= 1

    return max_score, alignment_s, alignment_t

# Input
s = "MEANLY"
t = "PENALTY"

score, alignment_s, alignment_t = local_alignment(s, t)

